fn run() -> Result<(), String> {
    let mut args = std::env::args().skip(1).peekable();
    if args.peek().is_some_and(|a| a == "--help" || a == "-h") {
        println!("{HELP}");
        return Ok(());
    }
    let command = if args.peek().is_some_and(|a| !a.starts_with('-')) {
        args.next().unwrap()
    } else {
        "check".into()
    };
    let allowed: &[&str] = match command.as_str() {
        "check" | "requirements" => &["--root", "--requirement"],
        "input" => &["--root", "--path", "--line-start", "--line-end"],
        _ => return Err(format!("unknown command {command}\n{HELP}")),
    };
    let mut options = BTreeMap::new();
    while let Some(key) = args.next() {
        if !allowed.contains(&key.as_str()) {
            return Err(format!("unknown option {key}\n{HELP}"));
        }
        let value = args
            .next()
            .filter(|v| !v.starts_with("--"))
            .ok_or_else(|| format!("missing value for {key}"))?;
        if options.insert(key.clone(), value).is_some() {
            return Err(format!("duplicate option {key}"));
        }
    }
    let root = PathBuf::from(options.get("--root").map(String::as_str).unwrap_or("."));
    if command == "input" {
        let get = |key: &str| options.get(key).ok_or_else(|| format!("missing {key}"));
        let start = get("--line-start")?
            .parse()
            .map_err(|_| "invalid --line-start")?;
        let end = get("--line-end")?
            .parse()
            .map_err(|_| "invalid --line-end")?;
        let input = snapshot(&root, get("--path")?, start, end)?;
        println!(
            "{}",
            serde_json::to_string_pretty(&input).map_err(|e| e.to_string())?
        );
        return Ok(());
    }
    let mut requirements = discover(&root)?;
    if let Some(id) = options.get("--requirement") {
        requirements.retain(|r| &r.id == id);
        if requirements.is_empty() {
            return Err(format!("unknown requirement {id}"));
        }
    }
    if command == "requirements" {
        println!(
            "{}",
            serde_json::to_string_pretty(&requirements).map_err(|e| e.to_string())?
        );
        return Ok(());
    }
    let errors: Vec<_> = requirements
        .iter()
        .flat_map(|r| validate(&root, r))
        .collect();
    if !errors.is_empty() {
        return Err(format!(
            "{}\nEvidence check failed: {} issue(s) across {} requirement(s).",
            errors.join("\n"),
            errors.len(),
            requirements.len()
        ));
    }
    if !options.contains_key("--requirement") {
        build_skill(&root)?;
    }
    println!(
        "Evidence is current for {} requirement(s). Justifications were not evaluated.",
        requirements.len()
    );
    Ok(())
}

pub fn snapshot(root: &Path, path: &str, start: usize, end: usize) -> Result<Input> {
    let root = root.canonicalize().map_err(|e| e.to_string())?;
    let text = read(&root, Path::new(path))?;
    Ok(Input {
        path: path.into(),
        line_start: start,
        line_end: end,
        contents: lines(&text, start, end)?,
    })
}

pub fn extract(path: &str, source: &str) -> Result<Vec<Requirement>> {
    let paragraphs: Vec<_> = Parser::new(source)
        .into_offset_iter()
        .filter_map(|(event, range)| matches!(event, Event::Start(Tag::Paragraph)).then_some(range))
        .collect();
    let mut requirements = Vec::new();
    let mut used = BTreeSet::new();
    for role in roles(source).into_iter().filter(|r| r.name == "req") {
        if !valid_id(&role.label) || !role.label.contains('.') {
            return Err(format!("{path}: invalid requirement ID {:?}", role.label));
        }
        let paragraph = paragraphs
            .iter()
            .find(|r| r.start <= role.range.start && r.end >= role.range.end)
            .ok_or_else(|| format!("{path}: {} must begin a paragraph", role.label))?;
        if !source[paragraph.start..role.range.start].trim().is_empty()
            || !used.insert(paragraph.start)
        {
            return Err(format!(
                "{path}: {} must be the only definition at the start of its paragraph",
                role.label
            ));
        }
        let text = source[role.range.end..paragraph.end].trim();
        if text.is_empty() {
            return Err(format!("{path}: {} has no requirement text", role.label));
        }
        requirements.push(Requirement {
            id: role.label,
            path: path.into(),
            line: source[..role.range.start]
                .bytes()
                .filter(|b| *b == b'\n')
                .count()
                + 1,
            requirement: text.into(),
        });
    }
    Ok(requirements)
}

fn cli_helpers_return_exact_text_and_failures_aggregate() {
    let f = Fixture::new();
    let output = f.cli(&["requirements", "--requirement", "test.rule"]);
    assert!(output.status.success());
    let data: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(data[0]["requirement"], "Preserve **all** data.");
    let output = f.cli(&[
        "input",
        "--path",
        "src/code.rs",
        "--line-start",
        "2",
        "--line-end",
        "3",
    ]);
    assert!(output.status.success());
    let data: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(data, f.evidence()["inputs"][0]);
    assert!(
        !f.0.join("evidence").exists(),
        "helpers must not write attestations"
    );
    f.write(
        "chapters/nested/contract.md",
        "{req}`test.rule` First.\n\n{req}`test.other` Second.",
    );
    let output = f.cli(&["check"]);
    assert!(!output.status.success());
    assert!(output.stdout.is_empty());
    let stderr = String::from_utf8(output.stderr).unwrap();
    assert!(stderr.contains("test.rule") && stderr.contains("test.other"));
    assert!(stderr.contains("2 issue(s)"));
}
